# Bounded state for a days-long run: when a ledger is over cap, halve it by
# insertion order -- no clock arithmetic, so a PTS restart cannot corrupt it.
# The override is events.state_cap in this config file.
state_cap = int((self.cfg.get('events') or {}).get('state_cap', 4096))
if len(self.emitted) > state_cap:
    for key in list(self.emitted)[:len(self.emitted) // 2]:
        self.emitted.pop(key)
        self.last_cand.pop(key, None)
if len(self.events) > state_cap:
    for key in list(self.events)[:len(self.events) // 2]:
        self.events.pop(key)
